     static inline void bitop(size_t *array, size_t bit, int op) {
         size_t idx = bit / (8 * sizeof *array);
         size_t mask = (1UL << (bit % (8 * sizeof *array)));
         switch (op) {
         case SET:   array[idx] |= mask; break;
         case CLEAR: array[idx] &= ~mask; break;
         case TOGGLE:array[idx] ^= mask; break;
