        $interval = null; // Initialize to null or handle directly
        try {
            $interval = new \DateInterval($deltaString);
        } catch (\Exception $initialException) {
            // If the constructor fails, try createFromDateString as a fallback
            $parsedInterval = \DateInterval::createFromDateString($deltaString);
            if (false === $parsedInterval) {
